def event(self, name: str, **values: object) -> dict[str, object]:
        skill_applied = bool(values.pop("_skill_applied", True))
        event = {
            "session_id": "session-1",
            "cwd": str(self.repo),
            "hook_event_name": name,
            **values,
        }
        if skill_applied:
            event["applied_skills"] = ["code-knowledge-builder"]
        return event
